export const FORMAL_UI_P5_MESSAGE_ROWS=(Object.keys(messages) as Array<keyof typeof messages>).map(key=>r(key,messages[key]))

function assertLocaleRows(rows:readonly Row[]){
 for(const row of rows)if(row.length!==11||row.slice(1).some(value=>!value.trim()))throw new Error(`invalid locale row: ${row[0]}`)
}
assertLocaleRows(FORMAL_UI_P5_MESSAGE_ROWS)
